			; 127: Else
			dw if4_e_go
if4_1:

			; 128: Print "FAIL("; got; ") ";
			dw kw_printstrvar, str31
			dw kw_printint, var_chk_got
			dw kw_printstrvar, str32

			; 129: bad = bad + 1
			dw kw_inc, var_bad

			; 130: End If
if4_e:
			dw p_chk_r

