kw_cls:		jp 147
kw_strleft:	jp 156
kw_strright:	jp 157
kw_strreplace:	jp 163
kw_strfix:	jp 167
kw_strsplit:	jp 171
kw_strmidset:	jp 172
kw_strmid:	jp 173
kw_strspace:	jp 178
kw_strstring:	jp 179
kw_strucase:	jp 180
kw_strasc:	jp 185
kw_strval:	jp 186
kw_sget:		jp 194
